package com.wissenup.domain.communication.entity; import jakarta.persistence.*; import lombok.*; import java.time.*;
@Entity @Table(name="organization_calendar") @Getter @Setter @Builder @NoArgsConstructor @AllArgsConstructor
public class CalendarEvent { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) @Column(name="calendar_id") private Long calendarId; @Column(name="organization_id") private Long organizationId; private String title; private String description; @Column(name="event_type") private String eventType; @Column(name="start_date") private LocalDate startDate; @Column(name="end_date") private LocalDate endDate; @Column(name="is_holiday") private Boolean isHoliday; @Column(name="color_code") private String colorCode; private String status; @Column(name="created_at") private LocalDateTime createdAt; @Column(name="created_by") private Long createdBy; @Column(name="updated_at") private LocalDateTime updatedAt; @Column(name="updated_by") private Long updatedBy; @PrePersist void create(){if(status==null)status="ACTIVE";if(isHoliday==null)isHoliday=false;if(createdAt==null)createdAt=LocalDateTime.now();}@PreUpdate void update(){updatedAt=LocalDateTime.now();} }
